@app.delete("/api/v1/compliance/retention-policies/{policy_id}/execute")
async def trigger_policy_purge(
    policy_id: int,
    request: Request,
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user)
):
    policy = db.query(RetentionPolicy).filter(
        RetentionPolicy.id == policy_id,
        RetentionPolicy.organization_id == current_user.organization_id
    ).first()
    if not policy:
        raise HTTPException(status_code=404, detail="Retention policy not found")
    purge_queue: asyncio.Queue = request.app.state.retention_purge_queue
    await purge_queue.put({"policy_id": policy.id, "target_table": policy.target_table, "cutoff_days": policy.cutoff_days})
    return {"queued": True, "policy_id": policy_id}
